    final usesLine = yaml
        .split('\n')
        .firstWhere(
          (l) => l.contains(
              'dmtools-agentic-workflows/.github/workflows/$workflowFile@'),
          orElse: () => '',
        );
    if (!usesLine.contains('@')) return null;
    final ref = usesLine.trim().split('@').last;
    // Immutable SHA-1, not a moving branch/tag ref.
    return ref;
  }

